            .clone();
        let rows_before = app
            .line_annotations
            .iter()
            .filter(|a| matches!(a, AnnotatedLine::RemoteThreadLine { .. }))
            .count();

        app.session
            .find_thread_mut(&thread_id)
            .unwrap()
            .thread
            .reply(crate::model::thread::ThreadComment::new(
                crate::model::thread::ThreadAuthor::human("alice"),
