            );
            assert_eq!(thread.status(), ThreadStatus::Stale);
            assert!(thread.anchor().is_stale());

            thread.resolve();
            assert_eq!(thread.status(), ThreadStatus::Resolved);
            assert!(thread.anchor().is_stale());
            assert!(thread.reopen());
            assert_eq!(thread.status(), ThreadStatus::Stale);
        }

